  status TEXT NOT NULL DEFAULT 'SUCCESS' CHECK (status IN ('SUCCESS', 'WARNING', 'ERROR', 'SKIPPED', 'FAILED')),
  target_object_type TEXT NOT NULL DEFAULT '',
