  definition_id bigint NOT NULL REFERENCES mig_definitions(id) ON DELETE CASCADE,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  sequence bigint NOT NULL DEFAULT 0,
  source_field TEXT NOT NULL DEFAULT '',
  target_field TEXT NOT NULL,
  mapping_type TEXT NOT NULL DEFAULT 'DIRECT',
  config_json TEXT NOT NULL DEFAULT '{}',
  required bigint NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive')),
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS mig_transformations (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  definition_id bigint NOT NULL REFERENCES mig_definitions(id) ON DELETE CASCADE,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  sequence bigint NOT NULL DEFAULT 0,
  stage TEXT NOT NULL DEFAULT 'FIELD',
  target_field TEXT NOT NULL DEFAULT '',
  transformation_type TEXT NOT NULL,
  config_json TEXT NOT NULL DEFAULT '{}',
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive')),
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS mig_validation_rules (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  definition_id bigint NOT NULL REFERENCES mig_definitions(id) ON DELETE CASCADE,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  sequence bigint NOT NULL DEFAULT 0,
  level TEXT NOT NULL DEFAULT 'FIELD',
  target_field TEXT NOT NULL DEFAULT '',
  rule_type TEXT NOT NULL,
  config_json TEXT NOT NULL DEFAULT '{}',
  severity TEXT NOT NULL DEFAULT 'ERROR',
  message TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive')),
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS mig_dependencies (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  project_id bigint NOT NULL REFERENCES mig_projects(id) ON DELETE CASCADE,
  package_id bigint NOT NULL REFERENCES mig_packages(id) ON DELETE CASCADE,
  depends_on_package_id bigint REFERENCES mig_packages(id) ON DELETE SET NULL,
  dependency_type TEXT NOT NULL DEFAULT 'PACKAGE',
  source_ref TEXT NOT NULL DEFAULT '',
  target_ref TEXT NOT NULL DEFAULT '',
  required bigint NOT NULL DEFAULT 1,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','satisfied','missing','circular')),
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS mig_plans (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  plan_ref TEXT NOT NULL DEFAULT '',
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  project_id bigint NOT NULL REFERENCES mig_projects(id) ON DELETE CASCADE,
  package_id bigint REFERENCES mig_packages(id) ON DELETE SET NULL,
  status TEXT NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','READY','BLOCKED','APPROVED','RUNNING','COMPLETED','FAILED')),
  summary_json TEXT NOT NULL DEFAULT '{}',
  generated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS mig_plan_steps (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  plan_id bigint NOT NULL REFERENCES mig_plans(id) ON DELETE CASCADE,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  sequence bigint NOT NULL DEFAULT 0,
  package_id bigint REFERENCES mig_packages(id) ON DELETE SET NULL,
  package_code TEXT NOT NULL DEFAULT '',
  dependency_json TEXT NOT NULL DEFAULT '[]',
  estimated_records bigint NOT NULL DEFAULT 0,
  estimated_duration_ms bigint NOT NULL DEFAULT 0,
  validation_status TEXT NOT NULL DEFAULT 'pending',
  readiness TEXT NOT NULL DEFAULT 'unknown',
  status TEXT NOT NULL DEFAULT 'pending',
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS mig_jobs (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  job_ref TEXT NOT NULL DEFAULT '',
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  organization_id bigint REFERENCES organizations(id) ON DELETE SET NULL,
  project_id bigint REFERENCES mig_projects(id) ON DELETE SET NULL,
  package_id bigint REFERENCES mig_packages(id) ON DELETE SET NULL,
  definition_id bigint REFERENCES mig_definitions(id) ON DELETE SET NULL,
  definition_version bigint NOT NULL DEFAULT 1,
  source_adapter TEXT NOT NULL DEFAULT '',
  mode TEXT NOT NULL DEFAULT 'EXECUTE' CHECK (mode IN ('DRY_RUN','EXECUTE','VALIDATE')),
  status TEXT NOT NULL DEFAULT 'QUEUED' CHECK (status IN ('QUEUED','PREPARING','VALIDATING','RUNNING','PAUSED','RETRYING','RECONCILING','COMPLETED','PARTIALLY_COMPLETED','FAILED','CANCELLED')),
  batch_size bigint NOT NULL DEFAULT 1000,
  worker_count bigint NOT NULL DEFAULT 1,
  total_records bigint NOT NULL DEFAULT 0,
  processed_records bigint NOT NULL DEFAULT 0,
  success_count bigint NOT NULL DEFAULT 0,
  failed_count bigint NOT NULL DEFAULT 0,
  duplicate_count bigint NOT NULL DEFAULT 0,
  rejected_count bigint NOT NULL DEFAULT 0,
  skipped_count bigint NOT NULL DEFAULT 0,
  updated_count bigint NOT NULL DEFAULT 0,
  retry_count bigint NOT NULL DEFAULT 0,
  checkpoint_json TEXT NOT NULL DEFAULT '{}',
  statistics_json TEXT NOT NULL DEFAULT '{}',
  params_json TEXT NOT NULL DEFAULT '{}',
  source_json TEXT NOT NULL DEFAULT '{}',
  idempotency_key TEXT NOT NULL DEFAULT '',
  error_message TEXT NOT NULL DEFAULT '',
  started_at TEXT,
  completed_at TEXT,
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS mig_batches (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  job_id bigint NOT NULL REFERENCES mig_jobs(id) ON DELETE CASCADE,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  batch_number bigint NOT NULL,
  status TEXT NOT NULL DEFAULT 'RUNNING' CHECK (status IN ('RUNNING','COMPLETED','FAILED','PARTIAL')),
  records bigint NOT NULL DEFAULT 0,
  success bigint NOT NULL DEFAULT 0,
  failed bigint NOT NULL DEFAULT 0,
  duplicates bigint NOT NULL DEFAULT 0,
  rejected bigint NOT NULL DEFAULT 0,
  skipped bigint NOT NULL DEFAULT 0,
  checkpoint_json TEXT NOT NULL DEFAULT '{}',
  started_at TEXT,
  completed_at TEXT,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (job_id, batch_number)
);

CREATE TABLE IF NOT EXISTS mig_checkpoints (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  job_id bigint NOT NULL REFERENCES mig_jobs(id) ON DELETE CASCADE,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  checkpoint_number bigint NOT NULL,
  last_record bigint NOT NULL DEFAULT 0,
  processed bigint NOT NULL DEFAULT 0,
  success bigint NOT NULL DEFAULT 0,
  failed bigint NOT NULL DEFAULT 0,
  state_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (job_id, checkpoint_number)
);

CREATE TABLE IF NOT EXISTS mig_object_results (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  job_id bigint NOT NULL REFERENCES mig_jobs(id) ON DELETE CASCADE,
  batch_id bigint REFERENCES mig_batches(id) ON DELETE SET NULL,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  record_number bigint NOT NULL DEFAULT 0,
  source_object_type TEXT NOT NULL DEFAULT '',
  source_object_id TEXT NOT NULL DEFAULT '',
  target_object_type TEXT NOT NULL DEFAULT '',
  target_object_id TEXT NOT NULL DEFAULT '',
  business_key TEXT NOT NULL DEFAULT '',
  action TEXT NOT NULL DEFAULT 'CREATE',
  status TEXT NOT NULL DEFAULT 'SUCCESS',
  mapped_json TEXT NOT NULL DEFAULT '{}',
  transformed_json TEXT NOT NULL DEFAULT '{}',
  validation_json TEXT NOT NULL DEFAULT '{}',
  message TEXT NOT NULL DEFAULT '',
  duration_ms bigint NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS mig_errors (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  job_id bigint NOT NULL REFERENCES mig_jobs(id) ON DELETE CASCADE,
  batch_id bigint REFERENCES mig_batches(id) ON DELETE SET NULL,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  package_id bigint REFERENCES mig_packages(id) ON DELETE SET NULL,
  record_number bigint NOT NULL DEFAULT 0,
  source_object_type TEXT NOT NULL DEFAULT '',
  source_object_id TEXT NOT NULL DEFAULT '',
  target_object_id TEXT NOT NULL DEFAULT '',
  field TEXT NOT NULL DEFAULT '',
  error_code TEXT NOT NULL DEFAULT '',
  error_type TEXT NOT NULL DEFAULT 'RECORD',
  category TEXT NOT NULL DEFAULT 'SYSTEM_ERROR',
  message TEXT NOT NULL DEFAULT '',
  retryable bigint NOT NULL DEFAULT 0,
  attempt_count bigint NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','RETRYING','RESOLVED','IGNORED','REJECTED')),
  details_json TEXT NOT NULL DEFAULT '{}',
  resolved_by bigint REFERENCES users(id) ON DELETE SET NULL,
  resolved_at TEXT,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS mig_retries (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  job_id bigint NOT NULL REFERENCES mig_jobs(id) ON DELETE CASCADE,
  error_id bigint REFERENCES mig_errors(id) ON DELETE SET NULL,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  attempt bigint NOT NULL DEFAULT 1,
  strategy TEXT NOT NULL DEFAULT 'MANUAL',
  status TEXT NOT NULL DEFAULT 'PENDING',
  error_message TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS mig_identifier_mappings (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  project_id bigint REFERENCES mig_projects(id) ON DELETE SET NULL,
  package_id bigint REFERENCES mig_packages(id) ON DELETE SET NULL,
  source_system TEXT NOT NULL DEFAULT '',
  source_object_type TEXT NOT NULL DEFAULT '',
  source_object_id TEXT NOT NULL,
  target_object_type TEXT NOT NULL DEFAULT '',
  target_object_id TEXT NOT NULL DEFAULT '',
  target_object_ref TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'MAPPED' CHECK (status IN ('MAPPED','PENDING','MISSING','REJECTED')),
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (tenant_id, source_system, source_object_type, source_object_id)
);

CREATE TABLE IF NOT EXISTS mig_relationship_mappings (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  project_id bigint REFERENCES mig_projects(id) ON DELETE SET NULL,
  package_id bigint REFERENCES mig_packages(id) ON DELETE SET NULL,
  job_id bigint REFERENCES mig_jobs(id) ON DELETE SET NULL,
  relationship_type TEXT NOT NULL DEFAULT '',
  source_relationship_id TEXT NOT NULL DEFAULT '',
  source_parent_id TEXT NOT NULL DEFAULT '',
  source_child_id TEXT NOT NULL DEFAULT '',
  target_parent_id TEXT NOT NULL DEFAULT '',
  target_child_id TEXT NOT NULL DEFAULT '',
  target_relationship_id TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'MAPPED' CHECK (status IN ('MAPPED','MISSING','SKIPPED','FAILED')),
  details_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS mig_reconciliations (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  reconciliation_ref TEXT NOT NULL DEFAULT '',
  job_id bigint NOT NULL REFERENCES mig_jobs(id) ON DELETE CASCADE,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  strategy TEXT NOT NULL DEFAULT 'COUNT',
  source_count bigint NOT NULL DEFAULT 0,
  processed_count bigint NOT NULL DEFAULT 0,
  successful_count bigint NOT NULL DEFAULT 0,
  failed_count bigint NOT NULL DEFAULT 0,
  duplicate_count bigint NOT NULL DEFAULT 0,
  rejected_count bigint NOT NULL DEFAULT 0,
  target_count bigint NOT NULL DEFAULT 0,
  variance bigint NOT NULL DEFAULT 0,
  reconciliation_percent double precision NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','COMPLETED','VARIANCE','FAILED')),
  report_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (job_id, strategy)
);

CREATE TABLE IF NOT EXISTS mig_reconciliation_exceptions (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  reconciliation_id bigint NOT NULL REFERENCES mig_reconciliations(id) ON DELETE CASCADE,
  job_id bigint REFERENCES mig_jobs(id) ON DELETE SET NULL,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  exception_type TEXT NOT NULL DEFAULT 'TARGET_MISSING',
  object_type TEXT NOT NULL DEFAULT '',
  source_object_id TEXT NOT NULL DEFAULT '',
  target_object_id TEXT NOT NULL DEFAULT '',
  field TEXT NOT NULL DEFAULT '',
  expected TEXT NOT NULL DEFAULT '',
  actual TEXT NOT NULL DEFAULT '',
  message TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS mig_statistics (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  job_id bigint REFERENCES mig_jobs(id) ON DELETE CASCADE,
  package_id bigint REFERENCES mig_packages(id) ON DELETE SET NULL,
  project_id bigint REFERENCES mig_projects(id) ON DELETE SET NULL,
  snapshot_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS mig_audit (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  organization_id bigint REFERENCES organizations(id) ON DELETE SET NULL,
  project_id bigint REFERENCES mig_projects(id) ON DELETE SET NULL,
  package_id bigint REFERENCES mig_packages(id) ON DELETE SET NULL,
  definition_version bigint NOT NULL DEFAULT 0,
  job_id bigint REFERENCES mig_jobs(id) ON DELETE SET NULL,
  batch_id bigint REFERENCES mig_batches(id) ON DELETE SET NULL,
  source_object_type TEXT NOT NULL DEFAULT '',
  source_object_id TEXT NOT NULL DEFAULT '',
  target_object_type TEXT NOT NULL DEFAULT '',
  target_object_id TEXT NOT NULL DEFAULT '',
  action TEXT NOT NULL DEFAULT 'MAPPED',
  status TEXT NOT NULL DEFAULT 'SUCCESS',
  error_message TEXT NOT NULL DEFAULT '',
  transformation_version bigint NOT NULL DEFAULT 0,
  correlation_id TEXT NOT NULL DEFAULT '',
  actor_user_id bigint REFERENCES users(id) ON DELETE SET NULL,
  actor_username TEXT NOT NULL DEFAULT '',
  details_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS mig_configuration (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  key TEXT NOT NULL,
  value_json TEXT NOT NULL DEFAULT 'null',
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (tenant_id, key)
);

CREATE TABLE IF NOT EXISTS mig_source_configurations (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  source_ref TEXT NOT NULL DEFAULT '',
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  code TEXT NOT NULL,
  name TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL DEFAULT '',
  adapter_type TEXT NOT NULL DEFAULT 'DATABASE',
  settings_json TEXT NOT NULL DEFAULT '{}',
  credential_ref TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive')),
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (tenant_id, code)
);

CREATE TABLE IF NOT EXISTS mig_file_migrations (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  project_id bigint REFERENCES mig_projects(id) ON DELETE SET NULL,
  package_id bigint REFERENCES mig_packages(id) ON DELETE SET NULL,
  job_id bigint REFERENCES mig_jobs(id) ON DELETE SET NULL,
  source_object_type TEXT NOT NULL DEFAULT '',
  source_object_id TEXT NOT NULL DEFAULT '',
  target_object_id TEXT NOT NULL DEFAULT '',
  original_filename TEXT NOT NULL DEFAULT '',
  mime_type TEXT NOT NULL DEFAULT 'application/octet-stream',
  file_size bigint NOT NULL DEFAULT 0,
  checksum TEXT NOT NULL DEFAULT '',
  storage_ref TEXT NOT NULL DEFAULT '',
  file_version TEXT NOT NULL DEFAULT '',
  upload_status TEXT NOT NULL DEFAULT 'PENDING' CHECK (upload_status IN ('PENDING','UPLOADED','FAILED','SKIPPED')),
  virus_scan_status TEXT NOT NULL DEFAULT 'UNKNOWN',
  status TEXT NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','MIGRATED','FAILED','SKIPPED')),
  error_message TEXT NOT NULL DEFAULT '',
  details_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS cla_classifications (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  classification_ref TEXT NOT NULL DEFAULT '',
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  organization_id bigint REFERENCES organizations(id) ON DELETE SET NULL,
  code TEXT NOT NULL,
  name TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','ACTIVE','SUPERSEDED','OBSOLETE')),
  version bigint NOT NULL DEFAULT 1,
  owner_user_id bigint REFERENCES users(id) ON DELETE SET NULL,
  steward_user_id bigint REFERENCES users(id) ON DELETE SET NULL,
  approval_status TEXT NOT NULL DEFAULT 'PENDING' CHECK (approval_status IN ('PENDING','APPROVED','REJECTED')),
  effective_date TEXT,
  obsolete_date TEXT,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (tenant_id, code)
);

CREATE TABLE IF NOT EXISTS cla_classification_versions (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  classification_id bigint NOT NULL REFERENCES cla_classifications(id) ON DELETE CASCADE,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  version bigint NOT NULL DEFAULT 1,
  status TEXT NOT NULL DEFAULT 'DRAFT',
  snapshot_json TEXT NOT NULL DEFAULT '{}',
  change_reason TEXT NOT NULL DEFAULT '',
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (classification_id, version)
);

CREATE TABLE IF NOT EXISTS cla_classes (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  class_ref TEXT NOT NULL DEFAULT '',
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  classification_id bigint NOT NULL REFERENCES cla_classifications(id) ON DELETE CASCADE,
  code TEXT NOT NULL,
  name TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL DEFAULT '',
  parent_class_id bigint REFERENCES cla_classes(id) ON DELETE RESTRICT,
  path TEXT NOT NULL DEFAULT '',
  level bigint NOT NULL DEFAULT 0,
  sort_order bigint NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','ACTIVE','SUPERSEDED','OBSOLETE')),
  version bigint NOT NULL DEFAULT 1,
  owner_user_id bigint REFERENCES users(id) ON DELETE SET NULL,
  effective_date TEXT,
  obsolete_date TEXT,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (tenant_id, classification_id, code)
);

CREATE TABLE IF NOT EXISTS cla_class_versions (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  class_id bigint NOT NULL REFERENCES cla_classes(id) ON DELETE CASCADE,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  version bigint NOT NULL DEFAULT 1,
  status TEXT NOT NULL DEFAULT 'DRAFT',
  snapshot_json TEXT NOT NULL DEFAULT '{}',
  change_reason TEXT NOT NULL DEFAULT '',
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (class_id, version)
);

CREATE TABLE IF NOT EXISTS cla_characteristics (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  characteristic_ref TEXT NOT NULL DEFAULT '',
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  code TEXT NOT NULL,
  name TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL DEFAULT '',
  data_type TEXT NOT NULL DEFAULT 'STRING',
  unit TEXT NOT NULL DEFAULT '',
  base_unit TEXT NOT NULL DEFAULT '',
  precision bigint,
  scale bigint,
  min_value double precision,
  max_value double precision,
  min_inclusive bigint NOT NULL DEFAULT 1,
  max_inclusive bigint NOT NULL DEFAULT 1,
  default_value TEXT NOT NULL DEFAULT '',
  multi_valued bigint NOT NULL DEFAULT 0,
  searchable bigint NOT NULL DEFAULT 1,
  required bigint NOT NULL DEFAULT 0,
  reference_type TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','INACTIVE','DEPRECATED')),
  version bigint NOT NULL DEFAULT 1,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (tenant_id, code)
);

CREATE TABLE IF NOT EXISTS cla_characteristic_versions (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  characteristic_id bigint NOT NULL REFERENCES cla_characteristics(id) ON DELETE CASCADE,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  version bigint NOT NULL DEFAULT 1,
  status TEXT NOT NULL DEFAULT 'ACTIVE',
  snapshot_json TEXT NOT NULL DEFAULT '{}',
  change_reason TEXT NOT NULL DEFAULT '',
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (characteristic_id, version)
);

CREATE TABLE IF NOT EXISTS cla_characteristic_groups (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  code TEXT NOT NULL,
  name TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL DEFAULT '',
  sort_order bigint NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','INACTIVE')),
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (tenant_id, code)
);

CREATE TABLE IF NOT EXISTS cla_characteristic_group_members (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  group_id bigint NOT NULL REFERENCES cla_characteristic_groups(id) ON DELETE CASCADE,
  characteristic_id bigint NOT NULL REFERENCES cla_characteristics(id) ON DELETE CASCADE,
  sequence bigint NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (group_id, characteristic_id)
);

CREATE TABLE IF NOT EXISTS cla_class_characteristics (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  class_id bigint NOT NULL REFERENCES cla_classes(id) ON DELETE CASCADE,
  characteristic_id bigint NOT NULL REFERENCES cla_characteristics(id) ON DELETE CASCADE,
  sequence bigint NOT NULL DEFAULT 0,
  required bigint NOT NULL DEFAULT 0,
  multi_valued bigint NOT NULL DEFAULT 0,
  origin TEXT NOT NULL DEFAULT 'LOCAL' CHECK (origin IN ('LOCAL','OVERRIDDEN')),
  override_required bigint NOT NULL DEFAULT 0,
  override_default bigint NOT NULL DEFAULT 0,
  unit_override TEXT NOT NULL DEFAULT '',
  min_value double precision,
  max_value double precision,
  allowed_value_mode TEXT NOT NULL DEFAULT 'INHERIT' CHECK (allowed_value_mode IN ('INHERIT','EXTEND','RESTRICT')),
  allowed_value_ids_json TEXT NOT NULL DEFAULT '[]',
  default_value TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','INACTIVE')),
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (class_id, characteristic_id)
);

CREATE TABLE IF NOT EXISTS cla_allowed_values (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  characteristic_id bigint NOT NULL REFERENCES cla_characteristics(id) ON DELETE CASCADE,
  code TEXT NOT NULL,
  display_name TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL DEFAULT '',
  sort_order bigint NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','INACTIVE')),
  effective_date TEXT,
  obsolete_date TEXT,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (characteristic_id, code)
);

CREATE TABLE IF NOT EXISTS cla_assignments (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  assignment_ref TEXT NOT NULL DEFAULT '',
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  organization_id bigint REFERENCES organizations(id) ON DELETE SET NULL,
  classification_id bigint NOT NULL REFERENCES cla_classifications(id) ON DELETE RESTRICT,
  class_id bigint NOT NULL REFERENCES cla_classes(id) ON DELETE RESTRICT,
  classification_version bigint NOT NULL DEFAULT 1,
  object_type TEXT NOT NULL,
  object_id TEXT NOT NULL,
  assigned_by bigint REFERENCES users(id) ON DELETE SET NULL,
  assigned_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','INACTIVE','OBSOLETE')),
  version bigint NOT NULL DEFAULT 1,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (tenant_id, object_type, object_id, class_id)
);

CREATE TABLE IF NOT EXISTS cla_assignment_values (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  assignment_id bigint NOT NULL REFERENCES cla_assignments(id) ON DELETE CASCADE,
  characteristic_id bigint NOT NULL REFERENCES cla_characteristics(id) ON DELETE CASCADE,
  sequence bigint NOT NULL DEFAULT 0,
  value_text TEXT NOT NULL DEFAULT '',
  value_number double precision,
  value_boolean bigint,
  value_date TEXT,
  value_reference TEXT NOT NULL DEFAULT '',
  unit TEXT NOT NULL DEFAULT '',
  normalized_value double precision,
  normalized_unit TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','INACTIVE')),
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS cla_rules (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  rule_ref TEXT NOT NULL DEFAULT '',
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  class_id bigint REFERENCES cla_classes(id) ON DELETE CASCADE,
  characteristic_id bigint REFERENCES cla_characteristics(id) ON DELETE CASCADE,
  rule_type TEXT NOT NULL DEFAULT 'REQUIRED',
  config_json TEXT NOT NULL DEFAULT '{}',
  severity TEXT NOT NULL DEFAULT 'ERROR' CHECK (severity IN ('ERROR','WARNING','INFO')),
  message TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','INACTIVE')),
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS cla_change_history (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  organization_id bigint REFERENCES organizations(id) ON DELETE SET NULL,
  entity_type TEXT NOT NULL DEFAULT '',
  entity_id bigint,
  entity_ref TEXT NOT NULL DEFAULT '',
  action TEXT NOT NULL DEFAULT '',
  version bigint NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT '',
  before_json TEXT NOT NULL DEFAULT '{}',
  after_json TEXT NOT NULL DEFAULT '{}',
  actor_user_id bigint REFERENCES users(id) ON DELETE SET NULL,
  actor_username TEXT NOT NULL DEFAULT '',
  correlation_id TEXT NOT NULL DEFAULT '',
  details_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS cla_configuration (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  key TEXT NOT NULL,
  value_json TEXT NOT NULL DEFAULT 'null',
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (tenant_id, key)
);

CREATE TABLE IF NOT EXISTS bom_headers (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  bom_ref TEXT NOT NULL DEFAULT '',
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  organization_id bigint REFERENCES organizations(id) ON DELETE SET NULL,
  plant_id bigint,
  site_id bigint,
  bom_number TEXT NOT NULL,
  name TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL DEFAULT '',
  bom_type TEXT NOT NULL DEFAULT 'EBOM' CHECK (bom_type IN ('EBOM','MBOM','BOP','OTHER')),
  owner_user_id bigint REFERENCES users(id) ON DELETE SET NULL,
  owner_object_id bigint,
  status TEXT NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','IN_REVIEW','RELEASED','SUPERSEDED','OBSOLETE')),
  lifecycle_state TEXT NOT NULL DEFAULT 'DRAFT',
  current_revision_id bigint,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  version bigint NOT NULL DEFAULT 1,
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (tenant_id, bom_number)
);

CREATE TABLE IF NOT EXISTS bom_revisions (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  revision_ref TEXT NOT NULL DEFAULT '',
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  organization_id bigint REFERENCES organizations(id) ON DELETE SET NULL,
  bom_id bigint NOT NULL REFERENCES bom_headers(id) ON DELETE CASCADE,
  revision_number TEXT NOT NULL,
  revision_sequence bigint NOT NULL DEFAULT 1,
  status TEXT NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','IN_REVIEW','RELEASED','SUPERSEDED','OBSOLETE')),
  lifecycle_state TEXT NOT NULL DEFAULT 'DRAFT',
  valid_from TEXT,
  valid_to TEXT,
  effectivity_json TEXT NOT NULL DEFAULT '{}',
  configuration_context TEXT NOT NULL DEFAULT '',
  variant_id bigint,
  variant_code TEXT NOT NULL DEFAULT '',
  baseline_id bigint,
  versioning_revision_id bigint,
  versioning_version_id bigint,
  object_id bigint,
  owner_user_id bigint REFERENCES users(id) ON DELETE SET NULL,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  version bigint NOT NULL DEFAULT 1,
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (bom_id, revision_number)
);

CREATE TABLE IF NOT EXISTS bom_lines (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  line_ref TEXT NOT NULL DEFAULT '',
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  organization_id bigint REFERENCES organizations(id) ON DELETE SET NULL,
  bom_revision_id bigint NOT NULL REFERENCES bom_revisions(id) ON DELETE CASCADE,
  parent_object_id TEXT,
  parent_object_type TEXT NOT NULL DEFAULT 'part',
  child_object_id TEXT,
  child_object_type TEXT NOT NULL DEFAULT 'part',
  child_revision TEXT NOT NULL DEFAULT '',
  quantity double precision NOT NULL DEFAULT 1,
  uom TEXT NOT NULL DEFAULT 'EA',
  normalized_quantity double precision,
  normalized_uom TEXT NOT NULL DEFAULT '',
  find_number TEXT NOT NULL DEFAULT '',
  sequence bigint NOT NULL DEFAULT 0,
  reference_designator TEXT NOT NULL DEFAULT '',
  usage TEXT NOT NULL DEFAULT 'DESIGN',
  optional bigint NOT NULL DEFAULT 0,
  substitute bigint NOT NULL DEFAULT 0,
  substitute_group_id TEXT NOT NULL DEFAULT '',
  effectivity_json TEXT NOT NULL DEFAULT '{}',
  variant_id bigint,
  variant_code TEXT NOT NULL DEFAULT '',
  configuration_context TEXT NOT NULL DEFAULT '',
  attributes_json TEXT NOT NULL DEFAULT '{}',
  notes TEXT NOT NULL DEFAULT '',
  line_status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (line_status IN ('DRAFT','ACTIVE','INACTIVE','OBSOLETE')),
  relationship_id bigint,
  version bigint NOT NULL DEFAULT 1,
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS bom_line_attributes (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  line_id bigint NOT NULL REFERENCES bom_lines(id) ON DELETE CASCADE,
  attribute_code TEXT NOT NULL,
  data_type TEXT NOT NULL DEFAULT 'STRING',
  attribute_value TEXT NOT NULL DEFAULT '',
  sequence bigint NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (line_id, attribute_code)
);

CREATE TABLE IF NOT EXISTS bom_substitutes (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  organization_id bigint REFERENCES organizations(id) ON DELETE SET NULL,
  bom_revision_id bigint NOT NULL REFERENCES bom_revisions(id) ON DELETE CASCADE,
  line_id bigint REFERENCES bom_lines(id) ON DELETE CASCADE,
  primary_object_id TEXT,
  substitute_object_id TEXT NOT NULL,
  substitute_object_type TEXT NOT NULL DEFAULT 'part',
  substitute_group TEXT NOT NULL DEFAULT '',
  priority bigint NOT NULL DEFAULT 1,
  ratio double precision NOT NULL DEFAULT 1,
  status TEXT NOT NULL DEFAULT 'ACTIVE',
  notes TEXT NOT NULL DEFAULT '',
  metadata_json TEXT NOT NULL DEFAULT '{}',
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS bom_baselines (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  baseline_ref TEXT NOT NULL DEFAULT '',
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  organization_id bigint REFERENCES organizations(id) ON DELETE SET NULL,
  bom_id bigint NOT NULL REFERENCES bom_headers(id) ON DELETE CASCADE,
  revision_id bigint NOT NULL REFERENCES bom_revisions(id) ON DELETE CASCADE,
  baseline_number TEXT NOT NULL,
  name TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','FROZEN','RETIRED')),
  source_revision_number TEXT NOT NULL DEFAULT '',
  immutable bigint NOT NULL DEFAULT 1,
  line_count bigint NOT NULL DEFAULT 0,
  snapshot_json TEXT NOT NULL DEFAULT '{}',
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  frozen_at TEXT,
  frozen_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (tenant_id, baseline_number)
);

CREATE TABLE IF NOT EXISTS bom_baseline_lines (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  baseline_id bigint NOT NULL REFERENCES bom_baselines(id) ON DELETE CASCADE,
  line_ref TEXT NOT NULL DEFAULT '',
  find_number TEXT NOT NULL DEFAULT '',
  sequence bigint NOT NULL DEFAULT 0,
  parent_object_id TEXT,
  parent_object_type TEXT NOT NULL DEFAULT 'part',
  child_object_id TEXT,
  child_object_type TEXT NOT NULL DEFAULT 'part',
  child_revision TEXT NOT NULL DEFAULT '',
  quantity double precision NOT NULL DEFAULT 1,
  uom TEXT NOT NULL DEFAULT 'EA',
  usage TEXT NOT NULL DEFAULT 'DESIGN',
  optional bigint NOT NULL DEFAULT 0,
  substitute bigint NOT NULL DEFAULT 0,
  reference_designator TEXT NOT NULL DEFAULT '',
  effectivity_json TEXT NOT NULL DEFAULT '{}',
  variant_code TEXT NOT NULL DEFAULT '',
  attributes_json TEXT NOT NULL DEFAULT '{}',
  level bigint NOT NULL DEFAULT 0,
  path TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS bom_transformation_definitions (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  definition_ref TEXT NOT NULL DEFAULT '',
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  organization_id bigint REFERENCES organizations(id) ON DELETE SET NULL,
  code TEXT NOT NULL,
  name TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL DEFAULT '',
  source_bom_type TEXT NOT NULL DEFAULT 'EBOM',
  target_bom_type TEXT NOT NULL DEFAULT 'MBOM',
  status TEXT NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','ACTIVE','INACTIVE')),
  mapping_count bigint NOT NULL DEFAULT 0,
  config_json TEXT NOT NULL DEFAULT '{}',
  version bigint NOT NULL DEFAULT 1,
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (tenant_id, code)
);

CREATE TABLE IF NOT EXISTS bom_transformation_mappings (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  definition_id bigint NOT NULL REFERENCES bom_transformation_definitions(id) ON DELETE CASCADE,
  mapping_ref TEXT NOT NULL DEFAULT '',
  source_path TEXT NOT NULL DEFAULT '',
  target_path TEXT NOT NULL DEFAULT '',
  mapping_type TEXT NOT NULL DEFAULT 'LINE' CHECK (mapping_type IN ('OBJECT','LINE','QUANTITY','ATTRIBUTE','CLASSIFICATION','RELATIONSHIP','CONSTANT')),
  expression TEXT NOT NULL DEFAULT '',
  default_value TEXT NOT NULL DEFAULT '',
  required bigint NOT NULL DEFAULT 0,
  sequence bigint NOT NULL DEFAULT 0,
  config_json TEXT NOT NULL DEFAULT '{}',
  status TEXT NOT NULL DEFAULT 'ACTIVE',
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS bom_transformation_runs (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  run_ref TEXT NOT NULL DEFAULT '',
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  organization_id bigint REFERENCES organizations(id) ON DELETE SET NULL,
  definition_id bigint REFERENCES bom_transformation_definitions(id) ON DELETE SET NULL,
  source_revision_id bigint REFERENCES bom_revisions(id) ON DELETE SET NULL,
  target_bom_id bigint,
  target_revision_id bigint,
  mode TEXT NOT NULL DEFAULT 'DRY_RUN' CHECK (mode IN ('DRY_RUN','EXECUTE')),
  status TEXT NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','RUNNING','COMPLETED','FAILED')),
  summary_json TEXT NOT NULL DEFAULT '{}',
  mapped_count bigint NOT NULL DEFAULT 0,
  unmapped_count bigint NOT NULL DEFAULT 0,
  warning_count bigint NOT NULL DEFAULT 0,
  error_count bigint NOT NULL DEFAULT 0,
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  started_at TEXT,
  completed_at TEXT,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS bom_validation_rules (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  rule_ref TEXT NOT NULL DEFAULT '',
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  code TEXT NOT NULL,
  name TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL DEFAULT '',
  rule_type TEXT NOT NULL DEFAULT 'CUSTOM',
  severity TEXT NOT NULL DEFAULT 'ERROR' CHECK (severity IN ('PASS','WARNING','ERROR')),
  config_json TEXT NOT NULL DEFAULT '{}',
  status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','INACTIVE')),
  sequence bigint NOT NULL DEFAULT 0,
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (tenant_id, code)
);

CREATE TABLE IF NOT EXISTS bom_validation_results (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  result_ref TEXT NOT NULL DEFAULT '',
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  organization_id bigint REFERENCES organizations(id) ON DELETE SET NULL,
  bom_id bigint REFERENCES bom_headers(id) ON DELETE CASCADE,
  revision_id bigint REFERENCES bom_revisions(id) ON DELETE CASCADE,
  scope TEXT NOT NULL DEFAULT 'REVISION',
  status TEXT NOT NULL DEFAULT 'PASS' CHECK (status IN ('PASS','WARNING','ERROR')),
  rule_count bigint NOT NULL DEFAULT 0,
  issue_count bigint NOT NULL DEFAULT 0,
  error_count bigint NOT NULL DEFAULT 0,
  warning_count bigint NOT NULL DEFAULT 0,
  duration_ms bigint NOT NULL DEFAULT 0,
  actor_user_id bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS bom_validation_issues (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  result_id bigint REFERENCES bom_validation_results(id) ON DELETE CASCADE,
  revision_id bigint REFERENCES bom_revisions(id) ON DELETE CASCADE,
  line_id bigint,
  line_ref TEXT NOT NULL DEFAULT '',
  rule_code TEXT NOT NULL DEFAULT '',
  severity TEXT NOT NULL DEFAULT 'ERROR' CHECK (severity IN ('PASS','WARNING','ERROR')),
  message TEXT NOT NULL DEFAULT '',
  field TEXT NOT NULL DEFAULT '',
  details_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS bom_comparisons (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  comparison_ref TEXT NOT NULL DEFAULT '',
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  organization_id bigint REFERENCES organizations(id) ON DELETE SET NULL,
  left_kind TEXT NOT NULL DEFAULT 'REVISION' CHECK (left_kind IN ('REVISION','BASELINE')),
  left_id bigint NOT NULL,
  right_kind TEXT NOT NULL DEFAULT 'REVISION' CHECK (right_kind IN ('REVISION','BASELINE')),
  right_id bigint NOT NULL,
  scope TEXT NOT NULL DEFAULT 'LINE' CHECK (scope IN ('LINE','RECURSIVE')),
  status TEXT NOT NULL DEFAULT 'COMPLETED',
  summary_json TEXT NOT NULL DEFAULT '{}',
  added_count bigint NOT NULL DEFAULT 0,
  removed_count bigint NOT NULL DEFAULT 0,
  modified_count bigint NOT NULL DEFAULT 0,
  unchanged_count bigint NOT NULL DEFAULT 0,
  match_count bigint NOT NULL DEFAULT 0,
  duration_ms bigint NOT NULL DEFAULT 0,
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS bom_comparison_results (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  comparison_id bigint NOT NULL REFERENCES bom_comparisons(id) ON DELETE CASCADE,
  change_type TEXT NOT NULL DEFAULT 'UNCHANGED' CHECK (change_type IN ('ADDED','REMOVED','MODIFIED','UNCHANGED')),
  line_ref TEXT NOT NULL DEFAULT '',
  child_object_id TEXT,
  child_object_type TEXT NOT NULL DEFAULT 'part',
  find_number TEXT NOT NULL DEFAULT '',
  path TEXT NOT NULL DEFAULT '',
  before_json TEXT NOT NULL DEFAULT '{}',
  after_json TEXT NOT NULL DEFAULT '{}',
  changes_json TEXT NOT NULL DEFAULT '[]',
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS bom_change_history (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  organization_id bigint,
  entity_type TEXT NOT NULL DEFAULT 'BOM',
  entity_id bigint,
  entity_ref TEXT NOT NULL DEFAULT '',
  action TEXT NOT NULL DEFAULT '',
  version bigint NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT '',
  before_json TEXT NOT NULL DEFAULT '{}',
  after_json TEXT NOT NULL DEFAULT '{}',
  actor_user_id bigint REFERENCES users(id) ON DELETE SET NULL,
  actor_username TEXT NOT NULL DEFAULT '',
  correlation_id TEXT NOT NULL DEFAULT '',
  details_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS bom_configuration (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  key TEXT NOT NULL,
  value_json TEXT NOT NULL DEFAULT 'null',
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (tenant_id, key)
);

CREATE TABLE IF NOT EXISTS pdm_items (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  item_ref TEXT NOT NULL DEFAULT '',
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  organization_id bigint REFERENCES organizations(id) ON DELETE SET NULL,
  plant_id bigint,
  site_id bigint,
  item_number TEXT NOT NULL,
  name TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL DEFAULT '',
  item_type TEXT NOT NULL DEFAULT 'PART' CHECK (item_type IN ('PART','PRODUCT','DOCUMENT','ASSEMBLY','OTHER')),
  owner_user_id bigint REFERENCES users(id) ON DELETE SET NULL,
  owner_object_id bigint,
  object_id bigint,
  classification_code TEXT NOT NULL DEFAULT '',
  current_revision_id bigint,
  status TEXT NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','IN_WORK','IN_REVIEW','RELEASED','OBSOLETE')),
  lifecycle_state TEXT NOT NULL DEFAULT 'DRAFT',
  lifecycle_assignment_id bigint,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  attributes_json TEXT NOT NULL DEFAULT '{}',
  version bigint NOT NULL DEFAULT 1,
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (tenant_id, item_number)
);

CREATE TABLE IF NOT EXISTS pdm_item_revisions (
