  revision_number TEXT NOT NULL,
  revision_sequence bigint NOT NULL DEFAULT 1,
  description TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','IN_WORK','IN_REVIEW','RELEASED','OBSOLETE')),
  lifecycle_state TEXT NOT NULL DEFAULT 'DRAFT',
  lifecycle_assignment_id bigint,
  valid_from TEXT,
  valid_to TEXT,
  effectivity_json TEXT NOT NULL DEFAULT '{}',
  configuration_context TEXT NOT NULL DEFAULT '',
  variant_id bigint,
  variant_code TEXT NOT NULL DEFAULT '',
  baseline_id bigint,
  versioning_revision_id bigint,
  versioning_version_id bigint,
  object_id bigint,
  owner_user_id bigint REFERENCES users(id) ON DELETE SET NULL,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  attributes_json TEXT NOT NULL DEFAULT '{}',
  version bigint NOT NULL DEFAULT 1,
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
