  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (rule_id, version_number)
);

CREATE TABLE IF NOT EXISTS pdm_baselines (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  baseline_ref TEXT NOT NULL DEFAULT '',
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  organization_id bigint REFERENCES organizations(id) ON DELETE SET NULL,
  baseline_number TEXT NOT NULL,
  name TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','RELEASED','FROZEN','RETIRED')),
  source_object_id TEXT,
  source_revision_id bigint REFERENCES pdm_item_revisions(id) ON DELETE SET NULL,
  item_id bigint REFERENCES pdm_items(id) ON DELETE SET NULL,
  revision_rule_id bigint REFERENCES pdm_revision_rules(id) ON DELETE SET NULL,
  configuration_rule_id bigint REFERENCES pdm_configuration_rules(id) ON DELETE SET NULL,
  baseline_date TEXT,
  immutable bigint NOT NULL DEFAULT 0,
  member_count bigint NOT NULL DEFAULT 0,
  snapshot_json TEXT NOT NULL DEFAULT '{}',
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  released_at TEXT,
  released_by bigint REFERENCES users(id) ON DELETE SET NULL,
  frozen_at TEXT,
  frozen_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
