);

CREATE TABLE IF NOT EXISTS pdm_baseline_members (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  baseline_id bigint NOT NULL REFERENCES pdm_baselines(id) ON DELETE CASCADE,
