  valid_from TEXT,
  valid_to TEXT,
  object_relationship_id bigint,
  attributes_json TEXT NOT NULL DEFAULT '{}',
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS pdm_references (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  reference_ref TEXT NOT NULL DEFAULT '',
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  organization_id bigint REFERENCES organizations(id) ON DELETE SET NULL,
  source_type TEXT NOT NULL,
  source_id TEXT NOT NULL,
  source_ref TEXT NOT NULL DEFAULT '',
  target_type TEXT NOT NULL,
  target_id TEXT NOT NULL,
  target_ref TEXT NOT NULL DEFAULT '',
  category TEXT NOT NULL DEFAULT 'OTHER',
  relationship_type TEXT NOT NULL DEFAULT '',
  metadata_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (tenant_id, source_type, source_id, target_type, target_id, category)
);

CREATE TABLE IF NOT EXISTS pdm_validation_rules (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  rule_ref TEXT NOT NULL DEFAULT '',
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  code TEXT NOT NULL,
  name TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL DEFAULT '',
  rule_type TEXT NOT NULL DEFAULT 'CUSTOM',
  severity TEXT NOT NULL DEFAULT 'ERROR' CHECK (severity IN ('PASS','WARNING','ERROR')),
  config_json TEXT NOT NULL DEFAULT '{}',
  status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','INACTIVE')),
  sequence bigint NOT NULL DEFAULT 0,
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (tenant_id, code)
);

CREATE TABLE IF NOT EXISTS pdm_validation_results (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  result_ref TEXT NOT NULL DEFAULT '',
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  organization_id bigint REFERENCES organizations(id) ON DELETE SET NULL,
  item_id bigint REFERENCES pdm_items(id) ON DELETE CASCADE,
  revision_id bigint REFERENCES pdm_item_revisions(id) ON DELETE CASCADE,
  dataset_id bigint REFERENCES pdm_datasets(id) ON DELETE CASCADE,
  scope TEXT NOT NULL DEFAULT 'ITEM',
  status TEXT NOT NULL DEFAULT 'PASS' CHECK (status IN ('PASS','WARNING','ERROR')),
  rule_count bigint NOT NULL DEFAULT 0,
  issue_count bigint NOT NULL DEFAULT 0,
  error_count bigint NOT NULL DEFAULT 0,
  warning_count bigint NOT NULL DEFAULT 0,
  duration_ms bigint NOT NULL DEFAULT 0,
  actor_user_id bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS pdm_validation_issues (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  result_id bigint REFERENCES pdm_validation_results(id) ON DELETE CASCADE,
  item_id bigint,
  revision_id bigint,
  dataset_id bigint,
  object_ref TEXT NOT NULL DEFAULT '',
  rule_code TEXT NOT NULL DEFAULT '',
  severity TEXT NOT NULL DEFAULT 'ERROR' CHECK (severity IN ('PASS','WARNING','ERROR')),
  message TEXT NOT NULL DEFAULT '',
  field TEXT NOT NULL DEFAULT '',
  details_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS pdm_change_history (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  organization_id bigint,
  entity_type TEXT NOT NULL DEFAULT 'ITEM',
  entity_id bigint,
  entity_ref TEXT NOT NULL DEFAULT '',
  action TEXT NOT NULL DEFAULT '',
  version bigint NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT '',
  before_json TEXT NOT NULL DEFAULT '{}',
  after_json TEXT NOT NULL DEFAULT '{}',
  actor_user_id bigint REFERENCES users(id) ON DELETE SET NULL,
  actor_username TEXT NOT NULL DEFAULT '',
  correlation_id TEXT NOT NULL DEFAULT '',
  details_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS pdm_configuration (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  key TEXT NOT NULL,
  value_json TEXT NOT NULL DEFAULT 'null',
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (tenant_id, key)
);

CREATE TABLE IF NOT EXISTS change_requests (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  request_ref TEXT NOT NULL DEFAULT '',
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  organization_id bigint REFERENCES organizations(id) ON DELETE SET NULL,
  request_number TEXT NOT NULL,
  title TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL DEFAULT '',
  category TEXT NOT NULL DEFAULT 'OTHER' CHECK (category IN ('DESIGN','PROCESS','DOCUMENTATION','SUPPLIER','QUALITY','OTHER')),
  priority TEXT NOT NULL DEFAULT 'NORMAL' CHECK (priority IN ('LOW','NORMAL','HIGH','URGENT')),
  status TEXT NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','SUBMITTED','SCREENING','APPROVED','REJECTED','WITHDRAWN','PROMOTED')),
  requested_by bigint REFERENCES users(id) ON DELETE SET NULL,
  reason TEXT NOT NULL DEFAULT '',
  object_id bigint,
  lifecycle_state TEXT NOT NULL DEFAULT 'DRAFT',
  lifecycle_assignment_id bigint,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  version bigint NOT NULL DEFAULT 1,
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (tenant_id, request_number)
);

CREATE TABLE IF NOT EXISTS change_orders (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  order_ref TEXT NOT NULL DEFAULT '',
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  organization_id bigint REFERENCES organizations(id) ON DELETE SET NULL,
  order_number TEXT NOT NULL,
  title TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL DEFAULT '',
  change_request_id bigint REFERENCES change_requests(id) ON DELETE SET NULL,
  status TEXT NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','IN_REVIEW','APPROVED','REJECTED','RELEASED','CANCELLED')),
  effective_strategy TEXT NOT NULL DEFAULT 'DATE' CHECK (effective_strategy IN ('DATE','IMMEDIATE','SERIAL')),
  effective_context_json TEXT NOT NULL DEFAULT '{}',
  requested_by bigint REFERENCES users(id) ON DELETE SET NULL,
  object_id bigint,
  lifecycle_state TEXT NOT NULL DEFAULT 'DRAFT',
  lifecycle_assignment_id bigint,
  released_at TEXT,
  released_by bigint REFERENCES users(id) ON DELETE SET NULL,
  baseline_id bigint,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  version bigint NOT NULL DEFAULT 1,
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (tenant_id, order_number)
);

CREATE TABLE IF NOT EXISTS change_notices (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  notice_ref TEXT NOT NULL DEFAULT '',
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  organization_id bigint REFERENCES organizations(id) ON DELETE SET NULL,
  notice_number TEXT NOT NULL,
  title TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL DEFAULT '',
  change_order_id bigint NOT NULL REFERENCES change_orders(id) ON DELETE CASCADE,
  status TEXT NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','ISSUED','ACKNOWLEDGED')),
  distribution_json TEXT NOT NULL DEFAULT '[]',
  issued_at TEXT,
  issued_by bigint REFERENCES users(id) ON DELETE SET NULL,
  acknowledged_at TEXT,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  version bigint NOT NULL DEFAULT 1,
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (tenant_id, notice_number)
);

CREATE TABLE IF NOT EXISTS change_affected_items (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  change_order_id bigint NOT NULL REFERENCES change_orders(id) ON DELETE CASCADE,
  object_type TEXT NOT NULL,
  object_id TEXT NOT NULL,
  object_label TEXT NOT NULL DEFAULT '',
  disposition TEXT NOT NULL DEFAULT 'NEW_REVISION' CHECK (disposition IN ('NEW_REVISION','OBSOLETE','NO_CHANGE','SUPERSEDED')),
  notes TEXT NOT NULL DEFAULT '',
  resulting_object_type TEXT,
  resulting_object_id TEXT,
  effectivity_definition_id bigint,
