  truncated bigint NOT NULL DEFAULT 0 CHECK (truncated IN (0,1)),
  consistency TEXT NOT NULL DEFAULT 'CURRENT' CHECK (consistency IN ('CURRENT','UPDATING','STALE','FAILED')),
