);

CREATE TABLE IF NOT EXISTS observability_health_checks (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  check_ref TEXT NOT NULL UNIQUE,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  code TEXT NOT NULL,
