  status TEXT NOT NULL DEFAULT 'ACTIVE',
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
