);

CREATE TABLE IF NOT EXISTS observability_health_snapshots (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  snapshot_ref TEXT NOT NULL UNIQUE,
  tenant_id bigint NOT NULL,
