);

CREATE TABLE IF NOT EXISTS observability_alert_rule_versions (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  rule_id bigint NOT NULL REFERENCES observability_alert_rules(id),
