);

CREATE TABLE IF NOT EXISTS observability_incidents (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  incident_ref TEXT NOT NULL UNIQUE,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  title TEXT NOT NULL,
