  tenant_id bigint NOT NULL,
  provider_code TEXT,
  metric_code TEXT,
  message TEXT NOT NULL DEFAULT '',
  detail_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS observability_metric_observations (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL,
  metric_id bigint REFERENCES observability_metric_definitions(id),
  metric_code TEXT NOT NULL,
  value double precision NOT NULL DEFAULT 0,
  unit TEXT NOT NULL DEFAULT '',
  dimension_json TEXT NOT NULL DEFAULT '{}',
  dimension_hash TEXT NOT NULL DEFAULT '',
  provider_code TEXT,
  run_id bigint REFERENCES observability_observation_runs(id),
  observed_at TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS observability_dashboards (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  dashboard_ref TEXT NOT NULL UNIQUE,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  organization_id bigint REFERENCES organizations(id),
  code TEXT NOT NULL,
  name TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  scope TEXT NOT NULL DEFAULT 'PLATFORM',
  is_default bigint NOT NULL DEFAULT 0,
  reporting_dashboard_ref TEXT,
  config_json TEXT NOT NULL DEFAULT '{}',
  version bigint NOT NULL DEFAULT 1,
  status TEXT NOT NULL DEFAULT 'ACTIVE',
  owner_user_id bigint REFERENCES users(id) ON DELETE SET NULL,
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS observability_dashboard_widgets (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  widget_ref TEXT NOT NULL UNIQUE,
  dashboard_id bigint NOT NULL REFERENCES observability_dashboards(id),
  tenant_id bigint NOT NULL,
  widget_type TEXT NOT NULL DEFAULT 'METRIC_CARD',
  title TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL DEFAULT '',
  metric_code TEXT,
  provider_code TEXT,
  visualization TEXT NOT NULL DEFAULT 'LINE',
  config_json TEXT NOT NULL DEFAULT '{}',
  layout_json TEXT NOT NULL DEFAULT '{}',
  sequence bigint NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'ACTIVE',
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS observability_history (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  action TEXT NOT NULL,
  entity_type TEXT NOT NULL DEFAULT 'metric',
  entity_id TEXT NOT NULL DEFAULT '',
  entity_ref TEXT NOT NULL DEFAULT '',
  actor_id bigint REFERENCES users(id) ON DELETE SET NULL,
  summary TEXT NOT NULL DEFAULT '',
  detail_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS observability_configuration (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  key TEXT NOT NULL,
  value_json TEXT NOT NULL DEFAULT 'null',
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS observability_retention_policies (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  tier TEXT NOT NULL,
  retain_days bigint NOT NULL DEFAULT 90,
  status TEXT NOT NULL DEFAULT 'ACTIVE',
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS observability_jobs (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  job_ref TEXT NOT NULL UNIQUE,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  handler_code TEXT NOT NULL,
  job_type_code TEXT NOT NULL,
  entity_type TEXT,
  entity_ref TEXT,
  platform_job_id bigint,
  status TEXT NOT NULL DEFAULT 'QUEUED',
  attempts bigint NOT NULL DEFAULT 0,
  max_attempts bigint NOT NULL DEFAULT 1,
  progress_json TEXT NOT NULL DEFAULT '{}',
  result_json TEXT NOT NULL DEFAULT '{}',
  error_message TEXT NOT NULL DEFAULT '',
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  queued_at TEXT,
  started_at TEXT,
  finished_at TEXT,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS deployment_profile (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY CHECK (id = 1),
  mode TEXT NOT NULL DEFAULT 'local' CHECK (mode IN ('saas', 'private_cloud', 'local')),
  edition TEXT NOT NULL DEFAULT 'enterprise' CHECK (edition IN ('community', 'standard', 'enterprise')),
  installation_name TEXT NOT NULL DEFAULT 'Helix',
  tenant_strategy TEXT NOT NULL DEFAULT 'multi' CHECK (tenant_strategy IN ('multi', 'single')),
  self_registration bigint NOT NULL DEFAULT 0 CHECK (self_registration IN (0, 1)),
  telemetry_enabled bigint NOT NULL DEFAULT 1 CHECK (telemetry_enabled IN (0, 1)),
  support_email TEXT NOT NULL DEFAULT '',
  notes TEXT NOT NULL DEFAULT '',
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS deployment_features (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  feature_code TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL DEFAULT '',
  category TEXT NOT NULL DEFAULT 'platform',
  description TEXT NOT NULL DEFAULT '',
  enabled bigint NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
  min_edition TEXT NOT NULL DEFAULT 'community' CHECK (min_edition IN ('community', 'standard', 'enterprise')),
  allowed_modes TEXT NOT NULL DEFAULT '',
  notes TEXT NOT NULL DEFAULT '',
  sort_order bigint NOT NULL DEFAULT 100,
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS deployment_history (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  action TEXT NOT NULL,
  entity_type TEXT NOT NULL DEFAULT 'profile',
  entity_ref TEXT NOT NULL DEFAULT '',
  before_json TEXT NOT NULL DEFAULT '{}',
  after_json TEXT NOT NULL DEFAULT '{}',
  details_json TEXT NOT NULL DEFAULT '{}',
  actor_user_id bigint REFERENCES users(id) ON DELETE SET NULL,
  actor_username TEXT NOT NULL DEFAULT '',
  ip TEXT,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS objects (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  uuid TEXT NOT NULL UNIQUE,
  code TEXT NOT NULL,
  object_type_id bigint NOT NULL REFERENCES metadata_types(id),
  name TEXT NOT NULL,
  description TEXT DEFAULT '',
  status TEXT NOT NULL DEFAULT 'draft'
    CHECK (status IN ('draft', 'active', 'released', 'obsolete', 'archived')),
  revision bigint NOT NULL DEFAULT 1,
  data_json TEXT NOT NULL DEFAULT '{}',
  owner_id bigint REFERENCES users(id),
  owner_object_id bigint REFERENCES objects(id),
  organization_id bigint REFERENCES organizations(id),
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  external_ref TEXT DEFAULT '',
  external_system TEXT DEFAULT '',
  tags_json TEXT NOT NULL DEFAULT '[]',
  created_by bigint REFERENCES users(id),
  updated_by bigint REFERENCES users(id),
  deleted_at TEXT,
  deleted_by bigint REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  lifecycle_version_id bigint REFERENCES lifecycle_versions(id),
  lifecycle_state_id bigint REFERENCES lifecycle_states(id),
  lifecycle_status_id bigint REFERENCES lifecycle_statuses(id)
);

CREATE TABLE IF NOT EXISTS object_versions (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  object_id bigint NOT NULL REFERENCES objects(id) ON DELETE CASCADE,
  revision bigint NOT NULL,
  change_type TEXT NOT NULL DEFAULT 'update',
  snapshot TEXT NOT NULL DEFAULT '{}',
  change_summary TEXT DEFAULT '',
  created_by bigint REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (object_id, revision)
);

CREATE TABLE IF NOT EXISTS object_checkouts (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  object_id bigint NOT NULL REFERENCES objects(id) ON DELETE CASCADE,
  locked_by bigint NOT NULL REFERENCES users(id),
  scope TEXT NOT NULL DEFAULT 'exclusive' CHECK (scope IN ('exclusive', 'shared')),
  reason TEXT DEFAULT '',
  expires_at TEXT,
  released_at TEXT,
  released_by bigint REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS object_relationships (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  relationship_type_id bigint NOT NULL REFERENCES relationship_types(id),
  source_object_id bigint NOT NULL REFERENCES objects(id),
  target_object_id bigint NOT NULL REFERENCES objects(id),
  status TEXT NOT NULL DEFAULT 'active'
    CHECK (status IN ('draft', 'active', 'inactive', 'expired')),
  sequence bigint NOT NULL DEFAULT 0,
  attributes_json TEXT NOT NULL DEFAULT '{}',
  valid_from TEXT,
  valid_to TEXT,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  created_by bigint REFERENCES users(id),
  deleted_at TEXT,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  UNIQUE (relationship_type_id, source_object_id, target_object_id)
);

CREATE TABLE IF NOT EXISTS object_references (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  source_object_id bigint NOT NULL REFERENCES objects(id),
  target_object_id bigint REFERENCES objects(id),
  reference_type TEXT NOT NULL DEFAULT 'weak'
    CHECK (reference_type IN ('strong', 'weak', 'external')),
  dependency bigint NOT NULL DEFAULT 0 CHECK (dependency IN (0, 1)),
  context TEXT DEFAULT '',
  external_ref TEXT DEFAULT '',
  external_system TEXT DEFAULT '',
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive')),
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  created_by bigint REFERENCES users(id),
  deleted_at TEXT,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS object_releases (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  object_id bigint NOT NULL REFERENCES objects(id) ON DELETE CASCADE,
  lifecycle_version_id bigint REFERENCES lifecycle_versions(id),
  transition_id bigint REFERENCES lifecycle_transitions(id),
  rule_id bigint REFERENCES approval_rules(id),
  from_state_id bigint REFERENCES lifecycle_states(id),
  to_state_id bigint REFERENCES lifecycle_states(id),
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'approved', 'rejected', 'changes_requested', 'cancelled')),
  requested_by bigint REFERENCES users(id),
  resolved_at TEXT,
  comments TEXT DEFAULT '',
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS object_approvals (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  release_id bigint NOT NULL REFERENCES object_releases(id) ON DELETE CASCADE,
  object_id bigint NOT NULL REFERENCES objects(id) ON DELETE CASCADE,
  step_id bigint REFERENCES approval_rule_steps(id),
  step_code TEXT DEFAULT '',
  sequence bigint NOT NULL DEFAULT 0,
  parallel bigint NOT NULL DEFAULT 0 CHECK (parallel IN (0, 1)),
  approver_type TEXT DEFAULT '',
  approver_id bigint,
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'approved', 'rejected', 'changes_requested', 'cancelled', 'skipped')),
  decided_by bigint REFERENCES users(id),
  decided_at TEXT,
  comment TEXT DEFAULT '',
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS object_status_history (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  object_id bigint NOT NULL REFERENCES objects(id) ON DELETE CASCADE,
  lifecycle_version_id bigint,
  transition_id bigint,
  from_state_id bigint,
  to_state_id bigint,
  from_status_id bigint,
  to_status_id bigint,
  from_status TEXT,
  to_status TEXT,
  source TEXT NOT NULL DEFAULT 'manual' CHECK (source IN ('manual', 'approval', 'system')),
  reason TEXT DEFAULT '',
  actor_id bigint REFERENCES users(id),
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS workflow_instances (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code TEXT NOT NULL,
  definition_id bigint NOT NULL REFERENCES workflow_definitions(id),
  version_id bigint NOT NULL REFERENCES workflow_versions(id),
  object_id bigint REFERENCES objects(id),
  parent_instance_id bigint REFERENCES workflow_instances(id),
  parent_node_id bigint REFERENCES workflow_nodes(id),
  title TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'running'
    CHECK (status IN ('pending', 'running', 'paused', 'completed', 'cancelled', 'failed')),
  context_json TEXT NOT NULL DEFAULT '{}',
  current_node_id bigint REFERENCES workflow_nodes(id),
  started_by bigint REFERENCES users(id),
  organization_id bigint REFERENCES organizations(id),
  started_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  ended_at TEXT,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS workflow_instance_nodes (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  instance_id bigint NOT NULL REFERENCES workflow_instances(id) ON DELETE CASCADE,
  node_id bigint NOT NULL REFERENCES workflow_nodes(id),
  node_key TEXT NOT NULL,
  node_type TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'active', 'blocked', 'completed', 'skipped', 'failed', 'cancelled')),
  outcome TEXT DEFAULT '',
  data_json TEXT NOT NULL DEFAULT '{}',
  entered_at TEXT,
  completed_at TEXT,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS workflow_tasks (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  instance_id bigint NOT NULL REFERENCES workflow_instances(id) ON DELETE CASCADE,
  instance_node_id bigint REFERENCES workflow_instance_nodes(id) ON DELETE CASCADE,
  definition_id bigint REFERENCES workflow_definitions(id),
  node_id bigint REFERENCES workflow_nodes(id),
  parent_task_id bigint REFERENCES workflow_tasks(id),
  code TEXT NOT NULL,
  title TEXT NOT NULL,
  description TEXT DEFAULT '',
  status TEXT NOT NULL DEFAULT 'unassigned'
    CHECK (status IN ('unassigned', 'assigned', 'in_progress', 'blocked', 'awaiting_approval', 'completed', 'cancelled')),
  priority TEXT NOT NULL DEFAULT 'normal' CHECK (priority IN ('low', 'normal', 'high', 'urgent')),
  assignee_type TEXT NOT NULL DEFAULT 'unassigned'
    CHECK (assignee_type IN ('unassigned', 'user', 'role', 'organization', 'group', 'queue')),
  assignee_id bigint,
  assignee_ref TEXT DEFAULT '',
  claimed_by bigint REFERENCES users(id),
  due_at TEXT,
  escalation_at TEXT,
  escalated bigint NOT NULL DEFAULT 0 CHECK (escalated IN (0, 1)),
  outcome TEXT DEFAULT '',
  form_json TEXT NOT NULL DEFAULT '{}',
  data_json TEXT NOT NULL DEFAULT '{}',
  object_id bigint REFERENCES objects(id),
  organization_id bigint REFERENCES organizations(id),
  completed_by bigint REFERENCES users(id),
  completed_at TEXT,
  created_by bigint REFERENCES users(id),
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS workflow_task_subtasks (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  task_id bigint NOT NULL REFERENCES workflow_tasks(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'todo' CHECK (status IN ('todo', 'done')),
  display_order bigint NOT NULL DEFAULT 0,
  completed_by bigint REFERENCES users(id),
  completed_at TEXT,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS workflow_task_comments (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  task_id bigint NOT NULL REFERENCES workflow_tasks(id) ON DELETE CASCADE,
  author_id bigint REFERENCES users(id),
  body TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS workflow_task_attachments (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  task_id bigint NOT NULL REFERENCES workflow_tasks(id) ON DELETE CASCADE,
  filename TEXT NOT NULL,
  url TEXT NOT NULL,
  content_type TEXT DEFAULT '',
  size bigint DEFAULT 0,
  uploaded_by bigint REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS workflow_approvals (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  instance_id bigint NOT NULL REFERENCES workflow_instances(id) ON DELETE CASCADE,
  task_id bigint REFERENCES workflow_tasks(id) ON DELETE CASCADE,
  node_id bigint REFERENCES workflow_nodes(id),
  node_key TEXT NOT NULL,
  approval_rule_id bigint REFERENCES approval_rules(id),
  step_id bigint REFERENCES approval_rule_steps(id),
  step_code TEXT DEFAULT '',
  sequence bigint NOT NULL DEFAULT 0,
  parallel bigint NOT NULL DEFAULT 0 CHECK (parallel IN (0, 1)),
  approver_type TEXT DEFAULT '',
  approver_id bigint,
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'approved', 'rejected', 'changes_requested', 'cancelled', 'skipped')),
  decided_by bigint REFERENCES users(id),
  decided_at TEXT,
  comment TEXT DEFAULT '',
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS workflow_events (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  instance_id bigint NOT NULL REFERENCES workflow_instances(id) ON DELETE CASCADE,
  task_id bigint REFERENCES workflow_tasks(id) ON DELETE SET NULL,
  node_key TEXT DEFAULT '',
  event_type TEXT NOT NULL,
  actor_id bigint REFERENCES users(id),
  message TEXT DEFAULT '',
  details_json TEXT NOT NULL DEFAULT '{}',
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS workflow_notifications (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  instance_id bigint REFERENCES workflow_instances(id) ON DELETE CASCADE,
  task_id bigint REFERENCES workflow_tasks(id) ON DELETE SET NULL,
  template_code TEXT DEFAULT '',
  channel TEXT NOT NULL DEFAULT 'in_app' CHECK (channel IN ('in_app', 'email', 'webhook')),
  recipient_type TEXT NOT NULL DEFAULT 'user' CHECK (recipient_type IN ('user', 'role', 'organization', 'group', 'queue')),
  recipient_id bigint,
  recipient_ref TEXT DEFAULT '',
  subject TEXT DEFAULT '',
  body TEXT DEFAULT '',
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'sent', 'failed', 'read')),
  payload_json TEXT NOT NULL DEFAULT '{}',
  sent_at TEXT,
  read_at TEXT,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS observability_alerts (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  alert_ref TEXT NOT NULL UNIQUE,
  tenant_id bigint NOT NULL REFERENCES organizations(id),
  rule_id bigint REFERENCES observability_alert_rules(id),
  rule_code TEXT,
  metric_code TEXT NOT NULL,
  service_code TEXT,
  severity TEXT NOT NULL DEFAULT 'WARNING',
  status TEXT NOT NULL DEFAULT 'OPEN',
  value double precision,
  threshold double precision,
  comparison TEXT,
  scope_json TEXT NOT NULL DEFAULT '{}',
  dedup_key TEXT NOT NULL DEFAULT '',
  message TEXT NOT NULL DEFAULT '',
  occurrence_count bigint NOT NULL DEFAULT 1,
  incident_id bigint REFERENCES observability_incidents(id),
  first_seen_at TEXT NOT NULL,
  last_seen_at TEXT NOT NULL,
  acknowledged_at TEXT,
  acknowledged_by bigint REFERENCES users(id) ON DELETE SET NULL,
  suppressed_until TEXT,
  resolved_at TEXT,
  resolved_by bigint REFERENCES users(id) ON DELETE SET NULL,
  closed_at TEXT,
  resolution TEXT NOT NULL DEFAULT '',
  metadata_json TEXT NOT NULL DEFAULT '{}',
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS')),
  updated_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

CREATE TABLE IF NOT EXISTS observability_alert_events (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  alert_id bigint NOT NULL REFERENCES observability_alerts(id),
  tenant_id bigint NOT NULL,
  event_type TEXT NOT NULL,
  value double precision,
  actor_id bigint REFERENCES users(id) ON DELETE SET NULL,
  message TEXT NOT NULL DEFAULT '',
  detail_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (to_char(now() at time zone 'utc','YYYY-MM-DD HH24:MI:SS'))
);

